WHERE datetime(CURRENT_TIMESTAMP, 'localtime') - datetime(birthday) > 34;

SELECT CAST(COUNT(CASE WHEN P.height < 180 AND PA.overall_rating > 70 THEN 1 END) AS REAL) * 100 / COUNT(P.id) AS percentage
FROM Player AS P
INNER JOIN Player_Attributes AS PA ON P.player_api_id = PA.player_api_id;

SELECT SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage_running_no_issue
FROM loan
WHERE amount < 100000;

SELECT account_id
FROM account
WHERE frequency = 'POPLATEK MESICNE';

SELECT A2, A13
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT STRFTIME('%Y', birth_date) AS birth_year
FROM client
WHERE client_id = 130;

SELECT expense_description
FROM expense
WHERE cost = (SELECT MAX(cost) FROM expense);

SELECT SUM(cost) AS total_pizza_cost
FROM expense
WHERE expense_description = 'Pizza';

SELECT COUNT(DISTINCT city) AS num_cities
FROM zip_code
WHERE county = 'Orange County' AND state = 'Virginia';

SELECT DISTINCT department
FROM major
WHERE college = 'College of Humanities and Social Sciences';

SELECT COUNT(*) AS num_presidents
FROM member
WHERE position = 'President';

SELECT SUM(major_name = 'Finance') / SUM(major_name = 'Physics') AS ratio
FROM major
JOIN member ON major.major_id = member.link_to_major;

SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';

SELECT SUM(CASE WHEN type = 'Community Service' THEN 1 ELSE 0 END) * 100.0 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(cost) AS total_parking_cost
FROM expense
WHERE expense_description = 'Parking';

SELECT SUM(cost) AS total_expense
FROM expense
WHERE expense_date = '2019-08-20';

SELECT DISTINCT county
FROM zip_code
WHERE type = 'PO Box';

SELECT SUM(b.remaining < 0) * 100.0 / COUNT(e.event_id) AS percentage_over_budget
FROM event e
JOIN budget b ON e.event_id = b.link_to_event;

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT first_name, last_name
FROM member
WHERE t_shirt_size = 'X-Large';

SELECT SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN p.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) AS difference
FROM publisher p
JOIN superhero s ON p.id = s.publisher_id;

SELECT SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) * 100.0 / COUNT(s.superhero_name) AS percentage
FROM superhero s
JOIN colour c ON s.eye_colour_id = c.id;

SELECT full_name
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

SELECT SUM(CASE WHEN superhero.gender_id = 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM superhero
WHERE superhero.alignment_id = 2;

SELECT superhero_name
FROM superhero
WHERE height_cm = (SELECT MAX(height_cm) FROM superhero);

SELECT hero_id
FROM hero_attribute
WHERE attribute_value = (SELECT MIN(attribute_value) FROM hero_attribute);

SELECT full_name
FROM superhero
WHERE superhero_name = 'Alien';

SELECT CAST(COUNT(CASE WHEN STRFTIME('%Y', Birthday) > '1930' THEN ID END) AS REAL) * 100 / COUNT(ID) AS percentage
FROM Patient
WHERE SEX = 'F';

SELECT SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) * 100.0 / COUNT(ID) AS inpatient_percentage
FROM Patient
WHERE strftime('%Y', Birthday) BETWEEN '1930' AND '1940';

SELECT CAST(COUNT(CASE WHEN Admission = '+' THEN 1 END) AS REAL) / NULLIF(COUNT(CASE WHEN Admission = '-' THEN 1 END), 0) AS inpatient_to_outpatient_ratio
FROM Patient
WHERE Diagnosis = 'SLE';

SELECT SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM Laboratory
WHERE `U-PRO` > 0 AND `U-PRO` < 30;

SELECT SUM(Patient.Diagnosis = 'BEHCET') * 100 / COUNT(*) AS percentage
FROM Patient
WHERE Patient.SEX = 'M' AND strftime('%Y', Patient.`First Date`) = '1981';

SELECT Description, Diagnosis
FROM Patient
WHERE ID = 48473;

SELECT COUNT(*) 
FROM Patient 
WHERE SEX = 'F' AND Diagnosis = 'APS';

SELECT CAST(SUM(SEX = 'F') AS REAL) / COUNT(SEX) * 100
FROM Patient
WHERE strftime('%Y', Birthday) = '1980' AND Diagnosis = 'RA';

SELECT Date
FROM Laboratory
WHERE ID = '48473' AND GOT >= 60;

SELECT COUNT(CASE WHEN Laboratory.GOT >= 60 AND Patient.Diagnosis = 'SLE' THEN 1 END) * 1.0 / COUNT(CASE WHEN Laboratory.GOT >= 60 THEN 1 END) AS percentage
FROM Laboratory
JOIN Patient ON Laboratory.ID = Patient.ID;

SELECT DISTINCT molecule_id
FROM atom
WHERE element = 'c';

SELECT atom_id, atom_id2
FROM connected
WHERE bond_id = 'TR000_2_5';

SELECT ROUND(SUM(bond_type = '=') * 1.0 / COUNT(bond_id), 5) AS percent
FROM bond
WHERE molecule_id = 'TR008';

SELECT ROUND(SUM(element = 'h') * 100.0 / COUNT(atom_id), 4) AS percent
FROM atom
WHERE molecule_id = 'TR206';

SELECT T1.bond_type
FROM bond AS T1
WHERE T1.molecule_id = 'TR000';

SELECT COUNT(DISTINCT bond_id) 
FROM connected 
WHERE atom_id = 'TR009_12' OR atom_id2 = 'TR009_12';

SELECT COUNT(DISTINCT molecule_id) 
FROM bond 
WHERE bond_type = '#';

SELECT COUNT(*) 
FROM connected 
WHERE atom_id LIKE 'TR%_19' OR atom_id2 LIKE 'TR%_19';

SELECT DISTINCT element
FROM atom
WHERE molecule_id = 'TR004';

SELECT element
FROM atom
WHERE atom_id NOT IN (SELECT atom_id FROM connected);

SELECT COUNT(*) AS total_atoms
FROM atom
WHERE element IN ('c', 'h');

SELECT molecule_id, label
FROM molecule
WHERE molecule_id IN ('TR000', 'TR001', 'TR002');

SELECT molecule_id
FROM molecule
WHERE label = '-';

SELECT bond_type
FROM bond
WHERE molecule_id BETWEEN 'TR000' AND 'TR050';

SELECT DISTINCT element
FROM atom
WHERE molecule_id = 'TR001';

SELECT DISTINCT molecule_id
FROM bond
WHERE bond_type = ' = ';

SELECT 100.0 * COUNT(DISTINCT molecule_id) / (SELECT COUNT(DISTINCT molecule_id) FROM molecule) AS percent_triple_bond_compounds
FROM bond
WHERE bond_type = '#';

SELECT 100.0 * SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT CASE WHEN label = '+' THEN 'yes' ELSE 'no' END AS is_carcinogenic
FROM molecule
WHERE molecule_id = 'TR151';

SELECT COUNT(*) 
FROM molecule 
WHERE label = '+';

SELECT SUM(CASE WHEN m.label = '+' AND a.element = 'h' THEN 1 ELSE 0 END) * 100.0 / COUNT(m.molecule_id) AS percentage
FROM molecule m
JOIN atom a ON a.molecule_id = m.molecule_id;

SELECT CASE WHEN label = '+' THEN 'yes' ELSE 'no' END AS is_carcinogenic
FROM molecule
WHERE molecule_id = 'TR124';

SELECT atom_id
FROM atom
WHERE molecule_id = 'TR186';

SELECT bond_type
FROM bond
WHERE molecule_id = 'TR007_4_19';

SELECT CAST(SUM(CASE WHEN m.label = '+' AND a.element = 'cl' THEN 1 ELSE 0 END) AS REAL) / COUNT(m.molecule_id) AS percentage
FROM molecule m
JOIN atom a ON m.molecule_id = a.molecule_id;

SELECT label
FROM molecule
WHERE molecule_id = 'TR000';

SELECT MAX("Free Meal Count (K-12)" * 1.0 / "Enrollment (K-12)") AS highest_eligible_free_rate
FROM frpm
WHERE "County Name" = 'Alameda';

SELECT CAST(SUM(CASE WHEN DOC = 54 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN DOC = 52 THEN 1 ELSE 0 END) AS ratio
FROM schools
WHERE StatusType = 'Merged' AND County = 'Orange';

SELECT CAST(SUM(CASE WHEN FundingType = 'Locally funded' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(FundingType)
FROM schools
WHERE County = 'Santa Clara';

SELECT MAX(AnswerCount)
FROM posts
WHERE OwnerUserId = (SELECT Id FROM users WHERE DisplayName = 'csgillespie');

SELECT Name
FROM badges
WHERE Date = '2010-07-19 19:39:08.0';

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT p.LastEditDate, p.LastEditorUserId
FROM posts p
WHERE p.Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(*) AS CommentCount
FROM comments
WHERE PostId = (SELECT Id FROM posts WHERE Score = (SELECT MAX(Score) FROM posts));

SELECT ExcerptPostId, WikiPostId
FROM tags
WHERE TagName = 'sample';

SELECT SUM(CASE WHEN Currency = 'CZK' THEN 1 ELSE 0 END) - SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS AmountOfMoreSMEs
FROM customers
WHERE Segment = 'SME';

SELECT 100.0 * SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) / COUNT(*) AS KAM_Euro_Percentage
FROM customers
WHERE Segment = 'KAM';

SELECT CAST(SUM(CASE WHEN Consumption > 528.3 THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM yearmonth
WHERE Date = '201202';

SELECT CAST(SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage
FROM gasstations
WHERE Country = 'SVK';

SELECT SUM(CASE WHEN Segment = 'premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS PremiumPercentage
FROM gasstations
WHERE Country = 'SVK';

SELECT player_api_id
FROM Player_Attributes
WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);

SELECT player_name, height
FROM Player
WHERE height = (SELECT MAX(height) FROM Player);

SELECT SUM(height) / COUNT(id) AS average_height
FROM Player
WHERE birthday >= '1990-01-01 00:00:00' AND birthday < '1996-01-01 00:00:00';
